{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "The proportion of people who will remain asymptomatic throughout the course of infection with severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), the cause of coronavirus disease 2019 (COVID-19), is not known. Studies that assess people at just one time point will overestimate the proportion of true asymptomatic infection...",
      "reason": "The rationale section describes the current state of knowledge and key uncertainties, including the unknown proportion of asymptomatic infection and misclassification bias in single time-point studies."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "The amount, and infectiousness, of asymptomatic SARS-CoV-2 infection will determine what kind of measures will prevent transmission most effectively.",
      "reason": "The importance and need for the review are explained in terms of its implications for choosing effective transmission-prevention measures."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "callout_0",
      "quote": "The first two versions of the review have been published as preprints [7,8].",
      "reason": "The manuscript cites previous versions of this living review (preprints [7,8]), and text_20 discusses other systematic reviews; however, the Introduction does not explicitly explain the need for the current review relative to those existing reviews/versions beyond the living-review framing."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of proportions of asymptomatic/presymptomatic SARS-CoV-2 infection and transmission, not a review of intervention effects, so no mechanism of action needs describing."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review addresses observational and modelling evidence on infection and transmission proportions, not a complex intervention or delivery context, so a logic model is not required."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "The objectives of this study were to address three questions: (1) Amongst people who become infected with SARS-CoV-2, what proportion do not experience symptoms at all during their infection? (2) Amongst people with SARS-CoV-2 infection who are asymptomatic when diagnosed, what proportion will develop symptoms later? (3) What proportion of SARS-CoV-2 transmission is accounted for by people who are either asymptomatic throughout infection or presymptomatic?",
      "reason": "The Introduction explicitly states the study objectives as three clearly formulated review questions, satisfying the requirement for an explicit statement of objectives/questions."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "The objectives of this study were to address three questions: (1) Amongst people who become infected with SARS-CoV-2, what proportion do not experience symptoms at all during their infection? (2) Amongst people with SARS-CoV-2 infection who are asymptomatic when diagnosed, what proportion will develop symptoms later? (3) What proportion of SARS-CoV-2 transmission is accounted for by people who are either asymptomatic throughout infection or presymptomatic?",
      "reason": "This is a review of prevalence/proportion estimation rather than intervention effects, so PICO is not strictly required. The questions do specify population (people with SARS-CoV-2 infection) and outcomes (proportions asymptomatic, presymptomatic, transmission contribution), partially covering comparison elements, but no formal PICO framing or planned comparisons is provided."
    }
  ],
  "confidence": 90
}

